public class MainActivity extends Activity {
 static final int GREEN=0xff2a5b42,INK=0xff23342a,MUTED=0xff667b6c,PAPER=0xfff1f6ee,RED=0xffac453e,OPEN=101,EXPORT=102,NOTICE=103;
 final Handler timerHandler=new Handler(Looper.getMainLooper());final List<Runnable> timers=new ArrayList<>();final Runnable tick=new Runnable(){public void run(){for(Runnable r:new ArrayList<>(timers))r.run();timerHandler.postDelayed(this,30000);}};
 Store store;LinearLayout body;ScrollView scroll;TextView banner;String page="Сегодня",clientId="",query="",lastError="";boolean showClosed=false,editing=false;String formKind="";byte[] pending;String pendingName;List<String[]> csv=new ArrayList<>();JSONObject formOriginal;
 interface Task{void run()throws Exception;}interface Capture{JSONObject get()throws Exception;}Capture capture;
 void attempt(Task t){try{t.run();}catch(Exception e){error(e.getMessage()==null?e.toString():e.getMessage());}}
 @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null){page=state.getString("page","Сегодня");clientId=state.getString("client","");query=state.getString("query","");showClosed=state.getBoolean("closed");pendingName=state.getString("pendingName");try{File f=new File(getCacheDir(),"crm-export");if(state.getBoolean("pending")&&f.exists())try(InputStream in=new FileInputStream(f)){pending=Store.read(in);}}catch(Exception ignored){}}
  shell();try{store=new Store(this);}catch(Exception e){recovery(e.getMessage());return;}
  if(state!=null&&!state.getString("form","").isEmpty()){attempt(()->edit(state.getString("form"),new JSONObject(state.getString("payload"))));}else{String id=getIntent().getStringExtra("orderId");if(id!=null&&!id.isEmpty()&&Model.find(store.data,"orders",id)!=null)orderDetails(id);else navigate(page);}
 }
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if(store!=null)attempt(()->{store.reload();String id=i.getStringExtra("orderId");if(id!=null&&Model.find(store.data,"orders",id)!=null)leave(()->orderDetails(id));else navigate("Сегодня");});}
 @Override protected void onResume(){super.onResume();timerHandler.removeCallbacks(tick);timerHandler.postDelayed(tick,30000);if(store!=null){Reminders.refresh(this);updateBanner();}}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("page",page);b.putString("client",clientId);b.putString("query",query);b.putBoolean("closed",showClosed);if(editing&&capture!=null)try{b.putString("form",formKind);b.putString("payload",capture.get().toString());}catch(Exception ignored){}if(pending!=null)try{try(FileOutputStream out=new FileOutputStream(new File(getCacheDir(),"crm-export"))){out.write(pending);}b.putBoolean("pending",true);b.putString("pendingName",pendingName);}catch(Exception ignored){}}
 void shell(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(GREEN);LinearLayout header=new LinearLayout(this);header.setOrientation(1);header.setPadding(dp(18),dp(16),dp(18),dp(12));LinearLayout brand=new LinearLayout(this);brand.setGravity(Gravity.CENTER_VERTICAL);ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.brand_mark);brand.addView(icon,new LinearLayout.LayoutParams(dp(40),dp(40)));TextView name=text("  Хрюшки · Заказы",22,Color.WHITE,true);brand.addView(name);header.addView(brand);banner=text("Клиенты, заказы и пожелания",12,0xffdceadd,false);header.addView(banner);root.addView(header);
  HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout nav=new LinearLayout(this);nav.setBackgroundColor(Color.WHITE);for(String p:new String[]{"Сегодня","Клиенты","Заказы","Пожелания","База и настройки"}){Button b=new Button(this);b.setText(p);b.setAllCaps(false);b.setTextColor(GREEN);b.setTextSize(13);b.setBackgroundColor(Color.TRANSPARENT);b.setOnClickListener(v->leave(()->{clientId="";query="";navigate(p);}));nav.addView(b);}hs.addView(nav);root.addView(hs);scroll=new ScrollView(this);scroll.setBackgroundColor(PAPER);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(16),dp(16),dp(16),dp(30));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);getWindow().setStatusBarColor(GREEN);getWindow().setNavigationBarColor(GREEN);if(Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,insets)->{Insets x=insets.getInsets(WindowInsets.Type.systemBars());root.setPadding(x.left,x.top,x.right,x.bottom);return insets;});}
 void updateBanner(){banner.setText(Reminders.enabled(this)?"● База на телефоне · уведомления включены":"● База на телефоне · уведомления отключены");}
 @Override protected void onPause(){timerHandler.removeCallbacks(tick);super.onPause();}
 void clear(String title){timers.clear();body.removeAllViews();csv=new ArrayList<>();TextView t=text(title,24,INK,true);t.setPadding(0,0,0,dp(12));body.addView(t);scroll.scrollTo(0,0);}
 void navigate(String p){if(store==null)return;editing=false;capture=null;page=p;attempt(()->{store.reload();switch(p){case "Клиент":clientDetails(clientId);break;case "Клиенты":clients();break;case "Заказы":orders();break;case "Пожелания":wishes();break;case "База и настройки":settings();break;default:dashboard();}updateBanner();});}
 void leave(Runnable r){if(editing)new AlertDialog.Builder(this).setTitle("Закрыть форму?").setMessage("Несохранённые изменения будут потеряны.").setPositiveButton("Закрыть",(d,w)->{editing=false;r.run();}).setNegativeButton("Продолжить ввод",null).show();else r.run();}
 @Override public void onBackPressed(){if(editing)leave(()->navigate(page));else if(!page.equals("Сегодня")){clientId="";navigate("Сегодня");}else super.onBackPressed();}
 TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}void note(String s){TextView t=text(s,13,MUTED,false);t.setPadding(0,dp(7),0,dp(10));body.addView(t);}
 Button button(String s,Task action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15);b.setTextColor(Color.WHITE);b.setBackgroundResource(R.drawable.button_bg);b.setPadding(dp(10),dp(8),dp(10),dp(8));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));b.setLayoutParams(p);b.setOnClickListener(v->attempt(action));return b;}
 LinearLayout card(String eyebrow,String title,String detail){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(16),dp(14),dp(16),dp(14));c.setBackgroundResource(R.drawable.card_bg);c.addView(text(eyebrow,12,MUTED,true));TextView name=text(title,20,GREEN,true);name.setPadding(0,dp(5),0,dp(5));c.addView(name);c.addView(text(detail,14,INK,false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));c.setLayoutParams(p);body.addView(c);return c;}
 void section(String s){TextView t=text(s,18,INK,true);t.setPadding(0,dp(16),0,dp(8));body.addView(t);}
 EditText field(String label,String v,boolean numeric){return fieldIn(body,label,v,numeric);}
 EditText fieldIn(LinearLayout parent,String label,String v,boolean numeric){TextView l=text(label,13,GREEN,true);l.setPadding(0,dp(10),0,0);parent.addView(l);EditText e=new EditText(this);e.setText(v);e.setTextColor(INK);e.setTextSize(16);e.setSingleLine(true);if(numeric)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);parent.addView(e,new LinearLayout.LayoutParams(-1,dp(50)));return e;}
 EditText dateField(String label,String v){EditText e=field(label+" · ДД.ММ.ГГГГ",v,false);Button pick=button("Выбрать дату",()->{LocalDate day;try{day=Model.date(value(e));}catch(Exception x){day=LocalDate.now();}new DatePickerDialog(this,(a,y,m,d)->e.setText(Model.day(LocalDate.of(y,m+1,d))),day.getYear(),day.getMonthValue()-1,day.getDayOfMonth()).show();});body.addView(pick);return e;}
 Spinner choice(String label,String[] values,String current){body.addView(text(label,13,GREEN,true));Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values));int index=Arrays.asList(values).indexOf(current);s.setSelection(Math.max(0,index));body.addView(s,new LinearLayout.LayoutParams(-1,dp(50)));return s;}
 CheckBox check(String label,boolean checked){CheckBox c=new CheckBox(this);c.setText(label);c.setTextColor(INK);c.setChecked(checked);body.addView(c);return c;}
 String value(EditText e){return e.getText().toString().trim();}String selected(Spinner s){return String.valueOf(s.getSelectedItem());}String money(BigDecimal n){NumberFormat f=NumberFormat.getNumberInstance(new Locale("ru","RU"));f.setMinimumFractionDigits(2);f.setMaximumFractionDigits(2);return f.format(n)+" ₽";}
 void error(String s){lastError=s;new AlertDialog.Builder(this).setTitle("Проверьте данные").setMessage(s).setPositiveButton("Понятно",null).show();}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void confirm(String title,String message,Task t){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("Подтвердить",(d,w)->attempt(t)).setNegativeButton("Отмена",null).show();}
 boolean match(JSONObject o){return query.isEmpty()||o.toString().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT));}
 String clientName(String id){JSONObject c=Model.find(store.data,"clients",id);return c==null?"Клиент не найден":Model.s(c,"name");}
 void search(){EditText q=field("Поиск по имени, городу, изделию, цвету или артикулу",query,false);body.addView(button("Найти",()->{query=value(q);navigate(page);}));}
 void filterClosed(){CheckBox c=check("Показать завершённые / отменённые",showClosed);c.setOnCheckedChangeListener((v,b)->{showClosed=b;navigate(page);});}
 void dashboard(){clear("Ничего не забыть");int active=0,late=0,wanted=0;for(JSONObject o:Model.list(store.data,"orders")){if(Model.openOrder(o))active++;if(Model.needsShipping(o)&&Model.due(o).atTime(store.data.optJSONObject("settings").optInt("deadlineHour",18),0).atZone(ZoneId.systemDefault()).toInstant().isBefore(Instant.now()))late++;}for(JSONObject w:Model.list(store.data,"wishes"))if(Model.openWish(w))wanted++;card("МАСТЕРСКАЯ",active+" заказов в работе",late+" просроченных отправок · "+wanted+" пожеланий");
  if(!Reminders.enabled(this)){note("Для напоминаний разрешите уведомления. После принудительной остановки через настройки Android откройте приложение снова.");body.addView(button("Включить уведомления",()->requestNotices()));}
  body.addView(button("+ Новый клиент",()->editClient(null)));section("Отправить в первую очередь");List<JSONObject> list=new ArrayList<>();for(JSONObject o:Model.list(store.data,"orders"))if(Model.needsShipping(o))list.add(o);list.sort(Comparator.comparing(o->Model.due(o)));if(list.isEmpty())note("Нет заказов, ожидающих отправки.");for(JSONObject o:list)orderCard(o);
  section("Ожидаем доставку");for(JSONObject o:Model.list(store.data,"orders"))if(Model.openOrder(o)&&!Model.s(o,"expected").isEmpty())card("Заказ №"+o.optInt("number"),clientName(Model.s(o,"clientId")),"Ожидаемая дата: "+Model.s(o,"expected")).setOnClickListener(v->orderDetails(Model.s(o,"id")));
  section("Пожелания: пора связаться");for(JSONObject w:Model.list(store.data,"wishes"))if(Model.openWish(w)&&(Model.s(w,"status").equals("Есть в наличии")||(!Model.s(w,"remindOn").isEmpty()&&!Model.date(Model.s(w,"remindOn")).isAfter(LocalDate.now()))))wishCard(w);
 }
 void clients(){clear("Клиенты");search();body.addView(button("+ Клиент",()->editClient(null)));CheckBox archived=check("Показать архив клиентов",showClosed);archived.setOnCheckedChangeListener((v,b)->{showClosed=b;navigate(page);});csv.add(new String[]{"Имя","Город","Канал","Контакт","Примечание","Архив"});for(JSONObject c:Model.list(store.data,"clients")){if(!match(c)||(!showClosed&&c.optBoolean("archived")))continue;long count=Model.list(store.data,"orders").stream().filter(o->Model.s(o,"clientId").equals(Model.s(c,"id"))).count();card(Model.s(c,"city")+" · "+Model.s(c,"channel"),Model.s(c,"name"),count+" заказов"+(c.optBoolean("archived")?" · архив":"")).setOnClickListener(v->{clientId=Model.s(c,"id");navigate("Клиент");});csv.add(new String[]{Model.s(c,"name"),Model.s(c,"city"),Model.s(c,"channel"),Model.s(c,"contact"),Model.s(c,"note"),String.valueOf(c.optBoolean("archived"))});}body.addView(button("Экспорт клиентов CSV",()->exportCsv()));}
 void clientDetails(String id){JSONObject c=Model.find(store.data,"clients",id);if(c==null){error("Клиент не найден");return;}page="Клиент";clientId=id;clear(Model.s(c,"name"));card(Model.s(c,"channel"),Model.s(c,"city"),Model.s(c,"contact")+"\n"+Model.s(c,"note"));body.addView(button("Изменить клиента",()->editClient(c)));if(!Model.s(c,"contact").isEmpty())body.addView(button("Скопировать контакт",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Контакт",Model.s(c,"contact")));toast("Контакт скопирован");}));body.addView(button("+ Оформить заказ",()->editOrder(Model.newOrder(store.data,id))));body.addView(button("+ Пожелание / предзаказ",()->editWish(null,id)));section("Заказы клиента");for(JSONObject o:Model.list(store.data,"orders"))if(Model.s(o,"clientId").equals(id))orderCard(o);section("Пожелания и предзаказы");for(JSONObject w:Model.list(store.data,"wishes"))if(Model.s(w,"clientId").equals(id))wishCard(w);}
 void edit(String kind,JSONObject payload)throws Exception{switch(kind){case "client":editClient(payload);break;case "order":editOrder(payload);break;case "wish":editWish(payload,Model.s(payload,"clientId"));break;}}
 void editClient(JSONObject original)throws Exception{editing=true;formKind="client";JSONObject c=original==null?new JSONObject():Model.copy(original);if(Model.s(c,"id").isEmpty())c.put("id",Model.id());clear(original==null?"Новый клиент":"Карточка клиента");EditText name=field("Имя",Model.s(c,"name"),false),city=field("Город",Model.s(c,"city"),false);Spinner channel=choice("Основной канал",Model.CHANNELS,Model.s(c,"channel"));EditText contact=field("Ссылка на профиль / телефон / ник",Model.s(c,"contact"),false),note=field("Заметки и предпочтения",Model.s(c,"note"),false);CheckBox archived=check("Клиент в архиве",c.optBoolean("archived"));capture=()->{JSONObject p=Model.copy(c);p.put("name",value(name));p.put("city",value(city));p.put("channel",selected(channel));p.put("contact",value(contact));p.put("note",value(note));p.put("archived",archived.isChecked());return p;};
  formButtons(()->{JSONObject next=capture.get();if(next.optBoolean("archived")){for(JSONObject o:Model.list(store.data,"orders"))Model.require(!Model.s(o,"clientId").equals(Model.s(next,"id"))||!Model.openOrder(o),"Сначала закройте активные заказы клиента");for(JSONObject w:Model.list(store.data,"wishes"))Model.require(!Model.s(w,"clientId").equals(Model.s(next,"id"))||!Model.openWish(w),"Сначала закройте активные пожелания клиента");}store.change(d->Model.upsert(d,"clients",next));editing=false;clientId=Model.s(next,"id");navigate("Клиент");});}
 void formButtons(Task save){body.addView(button("Сохранить",()->{save.run();Reminders.refresh(this);toast("Сохранено");}));body.addView(button("Назад",()->leave(()->navigate(page))));}
 void chooseClient(Task fallback,java.util.function.Consumer<String> action){List<JSONObject> clients=new ArrayList<>();for(JSONObject c:Model.list(store.data,"clients"))if(!c.optBoolean("archived"))clients.add(c);if(clients.isEmpty()){attempt(fallback);return;}String[] names=new String[clients.size()];for(int i=0;i<names.length;i++)names[i]=Model.s(clients.get(i),"name")+" · "+Model.s(clients.get(i),"city");new AlertDialog.Builder(this).setTitle("Выберите клиента").setItems(names,(d,w)->action.accept(Model.s(clients.get(w),"id"))).show();}
 void orders(){clear("Заказы");search();filterClosed();body.addView(button("+ Заказ",()->chooseClient(()->editClient(null),id->attempt(()->editOrder(Model.newOrder(store.data,id))))));List<JSONObject> orders=new ArrayList<>(Model.list(store.data,"orders"));orders.sort((x,y)->Integer.compare(y.optInt("number"),x.optInt("number")));csv.add(new String[]{"Номер","Клиент","Город","Канал","Статус","Оформлен","Отправить до","Отправлен","Доставка ожидается","Доставлен","Состав","Сумма","Предоплата","Остаток","Перевозчик","Трек","Комментарий"});for(JSONObject o:orders){JSONObject c=Model.find(store.data,"clients",Model.s(o,"clientId"));if((!showClosed&&!Model.openOrder(o))||(!match(o)&&!match(c)))continue;orderCard(o);csv.add(new String[]{String.valueOf(o.optInt("number")),clientName(Model.s(o,"clientId")),c==null?"":Model.s(c,"city"),Model.s(o,"channel"),Model.s(o,"status"),Model.s(o,"placed"),Model.s(o,"due"),Model.s(o,"shipped"),Model.s(o,"expected"),Model.s(o,"delivered"),itemsDescription(o),Model.value(Model.total(o)),Model.s(o,"prepaid"),Model.value(Model.total(o).subtract(Model.n(o,"prepaid"))),Model.s(o,"carrier"),Model.s(o,"tracking"),Model.s(o,"note")});}body.addView(button("Экспорт заказов CSV",()->exportCsv()));}
 String countdown(JSONObject o){if(!Model.needsShipping(o))return Model.s(o,"status");long seconds=Duration.between(Instant.now(),Model.due(o).atTime(store.data.optJSONObject("settings").optInt("deadlineHour",18),0).atZone(ZoneId.systemDefault()).toInstant()).getSeconds();long n=Math.abs(seconds);return (seconds<0?"Просрочено на ":"До отправки: ")+(n/86400)+" д "+(n%86400/3600)+" ч "+(n%3600/60)+" мин";}
 void orderCard(JSONObject o){String detail=clientName(Model.s(o,"clientId"))+" · "+Model.s(o,"channel")+"\n"+itemsDescription(o)+"\n"+countdown(o)+"\nОформлен: "+Model.s(o,"placed")+" · срок: "+Model.s(o,"due");LinearLayout c=card("Заказ №"+o.optInt("number")+" · "+Model.s(o,"status"),money(Model.total(o)),detail);TextView timer=(TextView)c.getChildAt(2);timers.add(()->timer.setText(clientName(Model.s(o,"clientId"))+" · "+Model.s(o,"channel")+"\n"+itemsDescription(o)+"\n"+countdown(o)+"\nОформлен: "+Model.s(o,"placed")+" · срок: "+Model.s(o,"due")));c.setOnClickListener(v->orderDetails(Model.s(o,"id")));}
 String itemsDescription(JSONObject o){StringBuilder b=new StringBuilder();for(JSONObject i:Model.list(o,"items")){if(b.length()>0)b.append("; ");b.append(Model.s(i,"name")).append(" × ").append(Model.s(i,"qty"));for(String k:new String[]{"sku","color","size"})if(!Model.s(i,k).isEmpty())b.append(" · ").append(Model.s(i,k));}return b.toString();}
 void orderDetails(String id){attempt(()->{store.reload();JSONObject o=Model.find(store.data,"orders",id);Model.require(o!=null,"Заказ не найден");editing=false;capture=null;page="Заказы";clear("Заказ №"+o.optInt("number"));LinearLayout countdownCard=card(Model.s(o,"status"),clientName(Model.s(o,"clientId")),"Канал: "+Model.s(o,"channel")+"\n"+countdown(o));timers.add(()->((TextView)countdownCard.getChildAt(2)).setText("Канал: "+Model.s(o,"channel")+"\n"+countdown(o)));note("Оформлен: "+Model.s(o,"placed")+"\nОтправить до: "+Model.s(o,"due")+"\nФактически отправлен: "+Model.s(o,"shipped")+"\nОжидаемая доставка: "+Model.s(o,"expected")+"\nПолучен: "+Model.s(o,"delivered"));for(JSONObject item:Model.list(o,"items"))card(Model.s(item,"sku"),Model.s(item,"name"),"Цвет: "+Model.s(item,"color")+" · Размер: "+Model.s(item,"size")+"\n"+Model.s(item,"qty")+" шт. × "+money(Model.n(item,"price")));card(o.optBoolean("pricesAgreed")?"СУММА ЗАКАЗА":"ЦЕНЫ ЕЩЁ НЕ СОГЛАСОВАНЫ",money(Model.total(o)),"Предоплата: "+money(Model.n(o,"prepaid"))+"\nОсталось: "+money(Model.total(o).subtract(Model.n(o,"prepaid"))));note("Доставка: "+Model.s(o,"carrier")+"\nТрек: "+Model.s(o,"tracking")+"\n"+Model.s(o,"note"));body.addView(button("Редактировать заказ",()->editOrder(o)));if(Model.needsShipping(o))body.addView(button("Отметить отправку",()->{JSONObject p=Model.copy(o);p.put("status","Отправлен");p.put("shipped",Model.today());editOrder(p);}));if(Model.s(o,"status").equals("Отправлен"))body.addView(button("Отметить получение",()->{JSONObject p=Model.copy(o);p.put("status","Доставлен");p.put("delivered",Model.today());editOrder(p);}));if(Model.openOrder(o))body.addView(button("Отменить заказ",()->confirm("Отменить заказ №"+o.optInt("number")+"?","Напоминания по нему прекратятся. Запись сохранится.",()->{store.change(d->{JSONObject p=Model.copy(Model.find(d,"orders",id));p.put("status","Отменён");p.remove("delivered");Model.upsert(d,"orders",p);});Reminders.refresh(this);orderDetails(id);})));if(!Model.s(o,"tracking").isEmpty())body.addView(button("Скопировать трек-номер",()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Трек",Model.s(o,"tracking")));toast("Трек-номер скопирован");}));body.addView(button("Карточка клиента",()->{clientId=Model.s(o,"clientId");navigate("Клиент");}));body.addView(button("История изменений",()->history(id)));});}
 class ItemForm {LinearLayout view;EditText name,sku,color,size,qty,price;ItemForm(JSONObject o,LinearLayout parent){view=new LinearLayout(MainActivity.this);view.setOrientation(1);view.setPadding(dp(12),dp(10),dp(12),dp(10));view.setBackgroundResource(R.drawable.card_bg);name=fieldIn(view,"Изделие",Model.s(o,"name"),false);sku=fieldIn(view,"Артикул (необязательно)",Model.s(o,"sku"),false);color=fieldIn(view,"Ткань / цвет",Model.s(o,"color"),false);size=fieldIn(view,"Размер",Model.s(o,"size"),false);qty=fieldIn(view,"Количество",Model.s(o,"qty").isEmpty()?"1":Model.s(o,"qty"),true);price=fieldIn(view,"Цена за штуку, ₽",Model.s(o,"price").isEmpty()?"0":Model.s(o,"price"),true);parent.addView(view);}
  JSONObject read()throws Exception{JSONObject i=new JSONObject();i.put("name",value(name));i.put("sku",value(sku));i.put("color",value(color));i.put("size",value(size));i.put("qty",value(qty));i.put("price",value(price));return i;}}
 void editOrder(JSONObject original)throws Exception{editing=true;capture=null;formKind="order";JSONObject o=Model.copy(original);clear(o.optInt("number")==0?"Новый заказ":"Заказ №"+o.optInt("number"));note("Клиент: "+clientName(Model.s(o,"clientId")));Spinner status=choice("Статус",Model.ORDER_STATES,Model.s(o,"status")),channel=choice("Канал этого заказа",Model.CHANNELS,Model.s(o,"channel"));EditText placed=dateField("Дата оформления",Model.s(o,"placed"));EditText due=dateField("Отправить до",Model.s(o,"due"));note("По умолчанию — "+store.data.optJSONObject("settings").optInt("dispatchDays",3)+" календарных дня. Если изменили оформление, пересчитайте срок кнопкой ниже.");body.addView(button("Пересчитать срок от даты оформления",()->due.setText(Model.day(Model.date(value(placed)).plusDays(store.data.optJSONObject("settings").optInt("dispatchDays",3))))));EditText shipped=dateField("Фактическая отправка (пусто, если не отправлен)",Model.s(o,"shipped"));EditText expected=dateField("Ожидаемая доставка · для уведомления",Model.s(o,"expected"));EditText delivered=dateField("Фактическое получение (если доставлен)",Model.s(o,"delivered"));
  section("Состав заказа");LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);body.addView(rows);List<ItemForm> forms=new ArrayList<>();List<JSONObject> items=Model.list(o,"items");if(items.isEmpty())items.add(new JSONObject());for(JSONObject item:items)addItem(rows,forms,item);body.addView(button("+ Ещё изделие",()->addItem(rows,forms,new JSONObject())));
  EditText delivery=field("Стоимость доставки в сумме заказа, ₽",Model.s(o,"deliveryCost").isEmpty()?"0":Model.s(o,"deliveryCost"),true),prepaid=field("Предоплата, ₽",Model.s(o,"prepaid").isEmpty()?"0":Model.s(o,"prepaid"),true);CheckBox agreed=check("Цены согласованы",o.optBoolean("pricesAgreed"));EditText carrier=field("Перевозчик: Ozon / СДЭК / Почта…",Model.s(o,"carrier"),false),tracking=field("Трек-номер",Model.s(o,"tracking"),false),comment=field("Пожелания к заказу / заметки",Model.s(o,"note"),false);
  capture=()->{JSONObject p=Model.copy(o);p.put("status",selected(status));p.put("channel",selected(channel));p.put("placed",value(placed));p.put("due",value(due));p.put("shipped",value(shipped));p.put("expected",value(expected));p.put("delivered",value(delivered));JSONArray a=new JSONArray();for(ItemForm f:forms)a.put(f.read());p.put("items",a);p.put("deliveryCost",value(delivery).isEmpty()?"0":value(delivery));p.put("prepaid",value(prepaid).isEmpty()?"0":value(prepaid));p.put("pricesAgreed",agreed.isChecked());p.put("carrier",value(carrier));p.put("tracking",value(tracking));p.put("note",value(comment));return p;};
  TextView sum=text("",18,GREEN,true);body.addView(sum);body.addView(button("Посчитать сумму и остаток",()->{JSONObject p=capture.get();sum.setText("Всего: "+money(Model.total(p))+"\nОстаток: "+money(Model.total(p).subtract(Model.n(p,"prepaid"))));}));note("Это справочные суммы заказа. В бухгалтерию они автоматически не переносятся.");formButtons(()->{JSONObject next=capture.get();store.change(d->Model.upsert(d,"orders",next));editing=false;orderDetails(Model.s(next,"id"));});}
 void addItem(LinearLayout parent,List<ItemForm> forms,JSONObject item){ItemForm f=new ItemForm(item,parent);forms.add(f);f.view.addView(button("Убрать эту позицию",()->{forms.remove(f);parent.removeView(f.view);}));}
 void wishes(){clear("Пожелания и предзаказы");search();filterClosed();body.addView(button("+ Пожелание / предзаказ",()->chooseClient(()->editClient(null),id->attempt(()->editWish(null,id)))));note("Поиск по изделию, цвету или артикулу покажет, кому обещали написать. Изменение статуса не отправляет сообщения клиентам.");csv.add(new String[]{"Клиент","Изделие","Артикул","Цвет","Размер","Количество","Статус","Связаться","Тип","Примечание"});for(JSONObject w:Model.list(store.data,"wishes")){JSONObject c=Model.find(store.data,"clients",Model.s(w,"clientId"));if((!showClosed&&!Model.openWish(w))||(!match(w)&&!match(c)))continue;wishCard(w);csv.add(new String[]{clientName(Model.s(w,"clientId")),Model.s(w,"product"),Model.s(w,"sku"),Model.s(w,"color"),Model.s(w,"size"),Model.s(w,"qty"),Model.s(w,"status"),Model.s(w,"remindOn"),Model.s(w,"kind"),Model.s(w,"note")});}body.addView(button("Экспорт пожеланий CSV",()->exportCsv()));}
 void wishCard(JSONObject w){card(Model.s(w,"kind")+" · "+Model.s(w,"status"),Model.s(w,"product"),clientName(Model.s(w,"clientId"))+"\n"+Model.s(w,"color")+" · "+Model.s(w,"size")+" · "+Model.s(w,"sku")+"\nКоличество: "+Model.s(w,"qty")+"\nСвязаться: "+Model.s(w,"remindOn")).setOnClickListener(v->wishDetails(Model.s(w,"id")));}
 void wishDetails(String id){attempt(()->{store.reload();JSONObject w=Model.find(store.data,"wishes",id);Model.require(w!=null,"Пожелание не найдено");page="Пожелания";editing=false;capture=null;clear("Пожелание клиента");card(Model.s(w,"status"),clientName(Model.s(w,"clientId")),Model.s(w,"product")+"\n"+Model.s(w,"color")+" · "+Model.s(w,"size")+" · "+Model.s(w,"sku")+"\n"+Model.s(w,"qty")+" шт.\n"+Model.s(w,"note"));note("Связаться: "+Model.s(w,"remindOn"));body.addView(button("Редактировать пожелание",()->editWish(w,Model.s(w,"clientId"))));if(!Model.s(w,"orderId").isEmpty())body.addView(button("Открыть созданный заказ",()->orderDetails(Model.s(w,"orderId"))));else if(Model.openWish(w))body.addView(button("Создать заказ из пожелания",()->confirm("Оформить подтверждённый заказ?","Будет создан заказ с сегодняшней датой и новым сроком отправки. Проверьте состав и цены.",()->{String[] orderId={""};store.change(d->orderId[0]=Model.s(Model.convertWish(d,id),"id"));Reminders.refresh(this);editOrder(Model.find(store.data,"orders",orderId[0]));})));body.addView(button("Карточка клиента",()->{clientId=Model.s(w,"clientId");navigate("Клиент");}));});}
 void editWish(JSONObject original,String cid)throws Exception{editing=true;capture=null;formKind="wish";JSONObject w=original==null?new JSONObject():Model.copy(original);if(original==null)Model.require(!Model.find(store.data,"clients",cid).optBoolean("archived"),"Сначала верните клиента из архива");if(Model.s(w,"id").isEmpty()){w.put("id",Model.id());w.put("clientId",cid);w.put("createdAt",Model.now());}clear("Пожелание / предзаказ");note("Клиент: "+clientName(cid));Spinner kind=choice("Тип",new String[]{"Пожелание","Предзаказ"},Model.s(w,"kind"));String[] states=Model.s(w,"orderId").isEmpty()?new String[]{"Ожидает","Есть в наличии","Клиенту сообщили","Отменено"}:new String[]{"Заказ создан"};Spinner status=choice("Статус",states,Model.s(w,"status"));EditText product=field("Желаемое изделие",Model.s(w,"product"),false),sku=field("Артикул (если известен)",Model.s(w,"sku"),false),color=field("Цвет / ткань",Model.s(w,"color"),false),size=field("Размер",Model.s(w,"size"),false),qty=field("Количество",Model.s(w,"qty").isEmpty()?"1":Model.s(w,"qty"),true);EditText remind=dateField("Напомнить связаться (необязательно)",Model.s(w,"remindOn"));EditText comment=field("Что именно обещали / особые пожелания",Model.s(w,"note"),false);note("Пожелание не запускает трёхдневный срок отправки. Таймер появится после оформления настоящего заказа.");capture=()->{JSONObject p=Model.copy(w);p.put("kind",selected(kind));p.put("status",selected(status));p.put("product",value(product));p.put("sku",value(sku));p.put("color",value(color));p.put("size",value(size));p.put("qty",value(qty));p.put("remindOn",value(remind));p.put("note",value(comment));return p;};formButtons(()->{JSONObject p=capture.get();store.change(d->Model.upsert(d,"wishes",p));editing=false;wishDetails(Model.s(p,"id"));});}
 void settings(){clear("База и настройки");note("Данные сохраняются на телефоне после каждого изменения. Синхронизации с бухгалтерией или другим устройством пока нет.");body.addView(button("Экспортировать полную базу JSON",()->export("hryushki_clients_"+System.currentTimeMillis()+".json","application/json",store.bytes())));body.addView(button("Импортировать / восстановить JSON",()->pick()));body.addView(button("Создать внутреннюю копию",()->{store.backup();toast("Копия создана");}));body.addView(button("Восстановить внутреннюю копию",()->backupDialog()));note("Хранятся 20 автоматических копий. Они удаляются при удалении приложения, поэтому регулярно экспортируйте JSON вне приложения.");section("Напоминания");note(Reminders.enabled(this)?"Уведомления разрешены.":"Уведомления отключены. Разрешите их, чтобы получать напоминания.");body.addView(button("Разрешить уведомления",()->requestNotices()));body.addView(button("Открыть настройки уведомлений Android",()->startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()))));body.addView(button("Проверить уведомление",()->Reminders.test(this)));
  JSONObject settings=store.data.optJSONObject("settings");EditText days=field("Срок отправки для новых заказов, календарных дней",String.valueOf(settings.optInt("dispatchDays",3)),true),hour=field("Час напоминаний, местное время (0–23)",String.valueOf(settings.optInt("reminderHour",9)),true),deadline=field("Час окончания срока отправки (0–23)",String.valueOf(settings.optInt("deadlineHour",18)),true);body.addView(button("Сохранить настройки",()->{int d=Integer.parseInt(value(days)),h=Integer.parseInt(value(hour)),dh=Integer.parseInt(value(deadline));store.change(data->{JSONObject n=data.getJSONObject("settings");n.put("dispatchDays",d);n.put("reminderHour",h);n.put("deadlineHour",dh);Model.validate(data);});Reminders.refresh(this);toast("Настройки сохранены");navigate(page);}));note("По умолчанию: отправка через 3 календарных дня до 18:00. Напоминания — накануне, в день срока и затем ежедневно при просрочке. Доставка и дата связи по пожеланию — однократно. Отправка / доставка / отмена прекращают соответствующие напоминания.");note("Уведомления не являются будильником: Android может задержать их в режиме экономии энергии. После перезагрузки расписание восстанавливается. Если принудительно остановили приложение в настройках телефона, запустите его снова. Время используется местное, по настройкам телефона.");String error=getSharedPreferences("reminders",0).getString("error","");if(!error.isEmpty())note("Последняя ошибка расписания: "+error);note("Хрюшки · Заказы 1.0 · работает без интернета. Сообщения клиентам приложение не отправляет.");}
 void requestNotices(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},NOTICE);else if(!Reminders.enabled(this))startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));else{Reminders.refresh(this);toast("Уведомления уже включены");}}
 @Override public void onRequestPermissionsResult(int request,String[] p,int[] r){super.onRequestPermissionsResult(request,p,r);if(request==NOTICE){Reminders.refresh(this);updateBanner();if(!editing)navigate(page);}}
 void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,OPEN);}
 void export(String name,String mime,byte[] bytes){pending=bytes;pendingName=name;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,EXPORT);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==OPEN)attempt(()->{JSONObject next;try(InputStream in=getContentResolver().openInputStream(uri)){next=Store.parse(Store.read(in));}confirm("Заменить текущую базу?","В файле "+Model.rows(next,"clients").length()+" клиентов и "+Model.rows(next,"orders").length()+" заказов. Импорт заменяет базу, а не объединяет записи. Перед заменой сохраняется копия.",()->{restore(next);navigate("Сегодня");});});else if(request==EXPORT)attempt(()->{Model.require(pending!=null,"Повторите экспорт");try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Файл недоступен");out.write(pending);out.flush();}pending=null;toast("Файл сохранён");});}
 void restore(JSONObject next)throws Exception{if(store==null){Model.validate(next);File f=new File(getFilesDir(),"clients-orders.json");if(f.exists()){try(InputStream in=new FileInputStream(f);OutputStream out=new FileOutputStream(new File(getFilesDir(),"damaged_"+System.currentTimeMillis()+".json"))){out.write(Store.read(in));}}android.util.AtomicFile af=new android.util.AtomicFile(f);FileOutputStream out=null;try{out=af.startWrite();out.write(next.toString().getBytes(StandardCharsets.UTF_8));af.finishWrite(out);}catch(Exception e){if(out!=null)af.failWrite(out);throw e;}store=new Store(this);}else store.replace(next);Reminders.refresh(this);}
 void backupDialog(){File dir=new File(getFilesDir(),"crm-backups");File[] a=dir.listFiles((d,n)->n.endsWith(".json"));if(a==null||a.length==0){toast("Копий пока нет");return;}Arrays.sort(a,(x,y)->Long.compare(y.lastModified(),x.lastModified()));String[] labels=new String[a.length];for(int j=0;j<a.length;j++)labels[j]=new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm:ss",Locale.ROOT).format(new Date(a[j].lastModified()));new AlertDialog.Builder(this).setTitle("Выберите копию").setItems(labels,(d,w)->confirm("Восстановить копию?","Текущая база будет заменена, перед заменой сохранится копия.",()->{JSONObject next;try(InputStream in=new FileInputStream(a[w])){next=Store.parse(Store.read(in));}restore(next);navigate("Сегодня");})).show();}
 void recovery(String error){clear("Восстановление данных");note("Не удалось открыть сохранённую базу: "+error);note("Повреждённый файл не заменён пустой базой. Его можно выгрузить для проверки либо восстановить копию.");body.addView(button("Выгрузить сохранённый файл",()->{android.util.AtomicFile f=new android.util.AtomicFile(new File(getFilesDir(),"clients-orders.json"));export("crm-recovery.json","application/json",f.readFully());}));body.addView(button("Открыть резервную копию",()->backupDialog()));body.addView(button("Импортировать исправленный JSON",()->pick()));}
 String escape(String s){if(s==null)s="";if(!s.isEmpty()&&"=+-@\t\r\n".indexOf(s.charAt(0))>=0)s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 void exportCsv(){StringBuilder b=new StringBuilder("\ufeff");for(String[] row:csv){for(int j=0;j<row.length;j++){if(j>0)b.append(';');b.append(escape(row[j]));}b.append("\r\n");}export("hryushki_crm_"+System.currentTimeMillis()+".csv","text/csv",b.toString().getBytes(StandardCharsets.UTF_8));}
 void history(String id){StringBuilder s=new StringBuilder();for(JSONObject e:Model.list(store.data,"audit"))if(Model.s(e,"id").equals(id)){s.append(Model.s(e,"at")).append(" · ").append(Model.s(e,"action").equals("create")?"Создано":"Изменено").append("\n");JSONObject before=e.optJSONObject("before");if(before!=null)s.append("До изменения: ").append(Model.s(before,"status")).append(" · срок ").append(Model.s(before,"due")).append("\n").append(Model.s(before,"note")).append("\n");s.append("\n");}new AlertDialog.Builder(this).setTitle("История заказа").setMessage(s.length()==0?"Изменений ещё нет":s.toString()).setPositiveButton("Закрыть",null).show();}
}
